import json,hashlib
pages={n:[] for n in range(339,349)}
units=[]
def a(n,ar,ru,cont=None):
 p=pages[n]; sid=f'v4-p{n:03d}-{len(p)+1:02d}'; p.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
 if cont:
  u=units[cont];u['source_ids'].append(sid);u['printed_pages'].append(n);u['ar']+=' '+ar;u['ru']+=' '+ru
 else:
  units.append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='self_reviewed',print_collation='control_image_read',independent_human_review=False))
 return len(units)-1
x=a(339,'فمنهم من يضعف لقوة الوارد، فلا يمكنه أن يتسع لغير ما باشر سره وقلبه من آثار الحب الخاص. ومنهم من يقوى فيتسع نظره، فيجد آثار الجلال، والجمال المقدس في قلبه وروحه، ويجد العبودية والمحبة والدعاء والافتقار والتوكل والخوف والرجاء وسائر الأعمال القلبية قائمة بقلبه، لا يشغله عن مشهد الروح، ولا يستغرقه مشهد الروح عنه. ويجد ملاحظته للأوامر والنواهي حاضرا في جذر قلبه حيث نزلت الأمانة، فلا يشغله مشهد الروح المستغرق، ولا مشهد القلب عن ملاحظة مراضي الرب تعالى ومحابه وحقه على عبده. ويجد ترك التدبير والاختيار وصحة التفويض موجودا في محل نفسه، فيعامل الله سبحانه بذلك، بحيث لا تشغله مشاهدة الأولى عنه. ويقوم بملاحظة عقله لأسرار حكمة الله في خلقه وأمره.','Среди них есть тот, кто слабеет от силы приходящего переживания и уже не способен вместить что-либо, кроме следов особой любви, непосредственно коснувшихся его сокровенной глубины и сердца. А другой обретает силу, и его взор становится шире: он находит в сердце и духе следы величия и святой красоты, а в сердце — рабское служение, любовь, мольбу, нужду в Аллахе, упование, страх, надежду и остальные дела сердца. Это не отвлекает его от созерцания духа, а созерцание духа не поглощает его настолько, чтобы отвлечь от этого. В самой глубине сердца, куда была ниспослана вверенная ответственность, он находит постоянное внимание к велениям и запретам. Ни всепоглощающее созерцание духа, ни созерцание сердца не отвлекают его от того, что угодно Всевышнему Господу и любимо Им, и от Его права над рабом. В своей душе он находит отказ от собственного распоряжения и выбора и правильное вверение дел Аллаху. Так он и обращается с Аллахом, Пречист Он, и созерцание прежде названного не отвлекает его от этого. Своим разумом он также следит за тайнами мудрости Аллаха в Его творении и велении.')
x=a(339,'ولا يحجبه ذلك كله عن ملاحظة عبوديته، فيبقى مغمور الروح بملاحظة الفردانية وجلالها وجمالها وكمالها، قد استغرقته محبته والشوق إليه، معمور القلب بعبادات القلوب، معمور العقل بملاحظة الحكمة ومعاني الخطاب، طاهر القلب عن سفاسف الأخلاق مع الله تعالى ومع الخلق، قد صار عبدا محضا لربه بروحه وقلبه وعقله ونفسه وبدنه وجوارحه، قد قام كل بما عليه من العبودية، بحيث لا تحجبه عبودية بعضه عن عبودية البعض الآخر، قد فني عن نفسه وبقي بربه. كما قال أبو بكر الكتاني: جرت مسألة في المحبة بمكة أيام الموسم، فتكلم الشيوخ فيها، وكان الجنيد أصغرهم','И всё это не заслоняет от него внимания к собственному рабскому служению. Дух его остаётся погружённым в созерцание единственности Господа, её величия, красоты и совершенства; его всецело охватывают любовь к Нему и тоска по Нему. Сердце исполнено сердечного поклонения, разум — внимания к мудрости и смыслам обращённой к нему речи, а сердце очищено от низких нравов в отношениях со Всевышним Аллахом и с творениями. Духом, сердцем, разумом, душой, телом и членами он становится всецело рабом своего Господа. Каждая его часть несёт положенное ей служение, и служение одной не заслоняет служения другой. Он утратил внимание к себе и пребывает благодаря своему Господу. Как сказал Абу Бакр аль-Каттани: «В дни хаджа в Мекке обсуждали любовь. Шейхи высказывались о ней, а аль-Джунайд был среди них самым младшим')
a(340,'سنا، فقالوا له: هات ما عندك يا عراقي؛ فأطرق ساعة، ودمعت عيناه، ثم قال: عبد ذاهب عن نفسه، متصل بذكر ربه، قائم بأداء حقوقه، ناظر إليه بقلبه، أحرق قلبه أنوار هيبته، وصفا شربه من كأس وده، وانكشف له الجبار من أستار غيبه، فإن تكلم فبالله، وإن نطق فمن الله، وإن تحرك فبأمر الله، وإن سكن فمع الله، فهو بالله ولله ومع الله؛ فبكى الشيوخ وقالوا: ما على هذا مزيد، جبرك الله يا تاج العارفين».','по возрасту. Ему сказали: „Поделись тем, что есть у тебя, о житель Ирака!“ Он на некоторое время опустил голову, его глаза наполнились слезами, а затем он сказал: „Это раб, утративший внимание к себе, неотступно поминающий своего Господа, исполняющий Его права, взирающий на Него сердцем. Свет благоговения перед Ним воспламенил его сердце, питьё из чаши Его любви стало чистым, а Всемогущий открылся ему из-за завес Своего сокрытого. Если он говорит, то благодаря Аллаху; если изрекает, то от Аллаха; если движется, то по велению Аллаха; если покоится, то с Аллахом. Он — благодаря Аллаху, ради Аллаха и с Аллахом“. Шейхи заплакали и сказали: „К этому нечего добавить. Да укрепит тебя Аллах, о венец познавших!“»',cont=x)
a(340,'فصل','Раздел')
a(340,'قال الشيخ: (الدرجة الثانية: فناء شهود الطلب لإسقاطه، وفناء شهود العلم لإسقاطه، وفناء شهود العيان لإسقاطه).','Шейх сказал: «Вторая ступень — фана созерцания поиска вследствие устранения этого созерцания, фана созерцания знания вследствие его устранения и фана созерцания непосредственного видения вследствие его устранения».')
a(340,'إنما كانت هذه الدرجة من الفناء أعلى عنده مما قبلها لأنها أبلغ في الفناء من جهة فناء أربابها عن فنائهم، قد سقط عن قلوبهم ذكر أحوالهم ومقاماتهم لما هم فيه من الشغل بربهم.','Эту ступень фана он считает выше предшествующей, поскольку она полнее: достигшие её утрачивают внимание к самому своему фана. Занятость Господом устраняет из их сердец воспоминание о собственных состояниях и стоянках.')
a(340,'وقوله: (لإسقاطه) أي: لإسقاط الشهود، لا لإسقاط المشهود، فالطلب والعلم والعيان قائم، وقد سقط شهوده لاستغراق صاحبه في المطلوب المعاين.','Его слова «вследствие его устранения» означают устранение созерцания, а не созерцаемого. Поиск, знание и непосредственное видение сохраняются, но человек перестаёт созерцать их, поскольку всецело погружён в искомое, которое непосредственно видит.')
a(341,'فصل','Раздел')
a(341,'قال: (الدرجة الثالثة: الفناء عن شهود الفناء، وهو الفناء حقا، شائما برق العين، راكبا بحر الجمع، سالكا سبيل البقاء).','Он сказал: «Третья ступень — фана от созерцания фана. Это и есть фана поистине: высматривая молнию непосредственного видения, плывя по морю объединённого созерцания и следуя путём пребывания».')
a(341,'الفرق بين الفناء في هذه الدرجة والتي قبلها أنه في التي قبلها قد فني عن شهود طلبه وعلمه وعيانه، مع شعوره بفنائه عن ذلك، وفي هذه الدرجة قد فني عن ذلك كله، وفني عن شهود فنائه، كما يقال: آخر من يموت ملك الموت.','Различие между фана на этой и предыдущей ступени в том, что на предыдущей человек утратил созерцание своего поиска, знания и непосредственного видения, но при этом ощущал своё фана от них. На этой же ступени он утратил внимание ко всему этому, а также к созерцанию собственного фана. Подобно тому как говорится: последним умирает ангел смерти.')
a(341,'وإنما كان هذا الفناء عنده هو الفناء حقا لأنه قد فني فيه كل ما سوى الحق سبحانه، لأن صاحبه الذي يشهد الفناء قد فني، فلم يبق سوى الواحد القهار.','Именно это фана он считает истинным, поскольку в нём исчезло всё, кроме Истинного, Пречист Он. Ведь сам тот, кто созерцал фана, утратил внимание к себе, и не осталось ничего, кроме Единственного, Всепокоряющего.')
a(341,'وقوله: (شائما برق العين)، الشائم: الناظر من بعد، وبرق العين: نور الحقيقة، وقد تقدم التنبيه على استحالة تعلق هذا بالنور الخارجي، وإنما هو أنوار القرب والمراقبة والحضور مع الله.','В выражении «высматривая молнию непосредственного видения» высматривающий — это тот, кто смотрит издали, а молния непосредственного видения — свет реальности. Ранее уже было указано, что здесь невозможно подразумевать внешний свет: речь идёт о свете близости, неусыпного внимания к Аллаху и присутствия с Ним.')
x=a(341,'وقوله: (راكبا بحر الجمع)، الجمع الذي يشيرون إليه عبارة عن','Его слова «плывя по морю объединённого созерцания». Объединённое созерцание, на которое они указывают, означает')
a(342,'شخوص البصيرة إلى مجرد مصدر المتفرقات كلها، كما سيأتي بيانه في بابه إن شاء الله تعالى، وركوب لجة هذا الجمع هو فناؤه فيه.','устремление внутреннего взора исключительно к Источнику всего разрозненного, как будет разъяснено в соответствующей главе, если пожелает Всевышний Аллах. Плыть по пучине такого объединения — это и есть его фана в нём.',cont=x)
a(342,'قوله: (سالكا سبيل البقاء)، يعني: أن من فني فقد تأهل للبقاء بالحق، وهذا البقاء هو بعد الفناء، فإنه إذا تحقق بالفناء رفع له علم الحقيقة، فشمر إليه سالكا في طريق البقاء، وهي القيام بالأوراد وحفظ الواردات، فحينئذ يرجى له الوصول.','Его слова «следуя путём пребывания» означают: достигший фана становится готов к пребыванию благодаря Истинному. Это пребывание наступает после фана. Когда человек действительно достигает фана, перед ним поднимается знамя реальности, и он усердно устремляется к нему путём пребывания: соблюдает установленные поминания и молитвы и бережёт приходящие к сердцу переживания. Тогда можно надеяться, что он достигнет цели.')
a(342,'فصل','Раздел')
a(342,'لم يرد في الكتاب، ولا في السنة، ولا في كلام الصحابة والتابعين مدح لفظ الفناء ولا ذمه، ولا استعملوا لفظه في هذا المعنى المشار إليه البتة، ولا ذكره مشايخ الطريق المتقدمون، ولا جعلوه غاية ولا مقاما، وقد كان القوم أحق بكل كمال، وأسبق إلى كل غاية محمودة.','Ни в Писании, ни в Сунне, ни в речах сподвижников и последователей нет ни похвалы слову «фана», ни его порицания. Они вообще не употребляли это слово в рассматриваемом смысле. Не упоминали его и ранние шейхи пути, не делали его ни целью, ни стоянкой, хотя эти люди более других обладали всяким совершенством и прежде других достигали всякой похвальной цели.')
a(342,'ونحن لا ننكر هذا اللفظ مطلقا، ولا نقبله مطلقا، بل لا بد فيه من التفصيل، وبيان صحيحه من معلوله، ووسيلته من غايته.','Мы не отвергаем это слово безусловно и не принимаем его безусловно. Необходимо подробно разобраться, отделить верное в нём от порочного, а средство — от цели.')
x=a(342,'فنقول — وبالله التوفيق، وهو الفتاح —: حقيقة الفناء المشار إليه هو استهلاك الشيء في الوجود العلمي الذهني، وهاهنا تقسمه أهل الاستقامة وأهل الزيغ والإلحاد، فزعم أهل الاتحاد — القائلين بوحدة الوجود — أن الفناء الذي هو غاية هو الفناء عن وجود السوى، فلا يثبت للسوى وجود','Итак, скажем — успех дарует Аллах, и Он Открывающий: сущность рассматриваемого фана — растворение чего-либо в познавательном, мысленном бытии. Здесь его по-разному понимают люди прямоты и люди уклонения и безбожия. Сторонники слияния, утверждающие единство бытия, полагают, что конечная цель фана — устранить бытие иного и вовсе не признавать за иным существования')
a(343,'البتة، لا في الشهود ولا في العيان، بل يتحقق بشهود وحدة الوجود، فيعلم حينئذ أن وجود جميع الموجودات هو عين وجود الحق، فما ثم وجودان، بل الموجود واحد. وحقيقة الفناء عندهم أن يفنى عما لا حقيقة له بل هو وهم وخيال، فيفنى عما هو فان في نفسه لا وجود له، فيشهد فناء وجود كل ما سواه في وجوده وحده، وهذا تعبير محض، وإلا في الحقيقة ليس عند القوم «سوى» ولا «غير»، وإنما السوى والغير في الوهم والخيال. فحول هذا الفناء يدندنون وعليه يحومون.','ни в созерцании, ни в непосредственном видении. Напротив, человек, по их утверждению, достигает созерцания единства бытия и тогда узнаёт, будто бытие всех существующих вещей тождественно бытию Истинного: двух бытий нет, а существующее одно. Сущность фана у них — утрата внимания к тому, что не имеет реальности и является лишь иллюзией и воображением. Человек утрачивает внимание к тому, что само по себе исчезающе и лишено бытия, и созерцает исчезновение бытия всего иного в Его единственном бытии. Впрочем, это лишь способ выражения: на самом деле для этих людей нет ни «иного», ни «другого», ибо иное и другое существуют лишь в иллюзии и воображении. Именно о таком фана они толкуют и вокруг него кружатся.',cont=x)
a(343,'وأما أهل التوحيد والاستقامة، فيشيرون بالفناء إلى أمرين أحدهما أرفع من الآخر:','Что же до приверженцев единобожия и прямоты, то они подразумевают под фана две вещи, одна из которых выше другой.')
a(343,'الأمر الأول: في شهود الربوبية والقيومية، فيشهد تفرد الرب تعالى بالقيومية، والتدبير، والخلق، والرزق، والعطاء، والمنع، والضر، والنفع، وأن جميع الموجودات منفعلة لا فاعلة، وما له منها فعل فهو منفعل في فعله، محل محض لجريان أحكام الربوبية عليه، لا يملك شيء منها لنفسه ولا لغيره ضرا ولا نفعا.','Первое — в созерцании господства и поддержания всего сущего. Человек созерцает исключительную принадлежность Всевышнему Господу поддержания всего сущего, управления, творения, наделения уделом, дарования, лишения, причинения вреда и пользы. Все существующие вещи испытывают воздействие, а не действуют независимо; даже та из них, которой свойственно действие, сама в своём действии испытывает воздействие. Она — лишь вместилище, в котором осуществляются установления господства. Ни одна вещь не властна причинить вред или пользу ни себе, ни другому.')
a(343,'فإذا تحقق بهذا المشهد خمدت منه الخواطر والإرادات، نظرا إلى القيوم الذي بيده تدابير الأمور، وشخوصا منه إلى مشيئته وحكمه، فهو ناظر منه به إليه، فان بشهوده عن شهود ما سواه. ومع هذا فهو ساع في طلب الوصول إليه، قائم بالواجبات والنوافل.','Когда человек действительно достигает этого созерцания, его помыслы и желания затихают: он взирает на Поддерживающего всё сущее, в Чьей Руке управление делами, и устремляет взор к Его воле и решению. От Него и благодаря Ему он взирает на Него, утратив в созерцании Его созерцание всего иного. При этом он продолжает стремиться к достижению Его, исполняя обязательные и дополнительные дела поклонения.')
a(344,'الأمر الثاني: الفناء في مشهد الإلهية، وحقيقته: الفناء عن إرادة ما سوى الله ومحبته، والإنابة إليه، والتوكل عليه، وخوفه ورجائه؛ فيفنى بحبه عن حب ما سواه، وبخوفه ورجائه عن خوف ما سواه ورجائه. وحقيقة هذا الفناء: إفراد الرب سبحانه بالمحبة والخوف والرجاء والتعظيم والإجلال.','Второе — фана в созерцании божественности. Сущность его — утрата желания чего-либо, кроме Аллаха, любви к иному, обращения к иному, упования на иное, страха перед иным и надежды на иное. Любовь к Нему устраняет любовь к иному, а страх перед Ним и надежда на Него устраняют страх перед иным и надежду на иное. Сущность этого фана — посвящать одному Господу, Пречист Он, любовь, страх, надежду, почитание и благоговение.')
a(344,'ونحن نشير إلى مبادئ ذلك وتوسطه وغايته:','Укажем на его начало, середину и завершение.')
a(344,'اعلم أن القلب إذا خلا من الاهتمام بالدنيا والتعلق بما فيها من مال أو رياسة أو صورة، وتعلق بالآخرة، والاهتمام بها من تحصيل العدة، والتأهب للقدوم على الله سبحانه = فذلك أول فتوحه وتباشير فجره، فعند ذلك يتحرك قلبه لمعرفة ما يرضى ربه منه فيفعله ويتقرب به إليه، وما يسخطه منه فيجتنبه.','Знай: когда сердце освобождается от заботы о земном мире и привязанности к его богатству, власти или обликам и привязывается к будущей жизни, заботится о ней, собирая припасы и готовясь предстать перед Аллахом, Пречист Он, — это первое открытие для него и предвестие его рассвета. Тогда его сердце устремляется узнать, какие его дела угодны Господу, чтобы совершать их и приближаться ими к Нему, и какие вызывают Его гнев, чтобы избегать их.')
a(344,'وهذا عنوان صدق إرادته، فإن كل من أيقن بلقاء الله وأنه سائله عن كلمتين يسأل عنهما الأولون والآخرون: ماذا كنتم تعبدون؟ وماذا أجبتم المرسلين؟ = لا بد أن يتنبه لطلب معرفة معبوده والطريق الموصلة إليه، فإذا تمكن في ذلك فتح له باب الأنس بالخلوة والوحدة والأماكن الخالية التي تهدأ فيها الأصوات والحركات، فلا شيء أشوق إليه من ذلك، فإنها تجمع عليه قوى قلبه وإرادته، وتسد عليه الأبواب التي تفرق همه وتشتت قلبه، فيأنس بها ويستوحش من الخلق.','Это признак искренности его стремления. Ведь всякий, кто убеждён во встрече с Аллахом и в том, что Он спросит его о двух вещах, о которых спросят первых и последних: «Кому вы поклонялись?» и «Что вы ответили посланникам?» — непременно пробудится к поиску познания Того, Кому поклоняется, и пути, ведущего к Нему. Когда он утвердится в этом, ему откроется дверь отрады в уединении, одиночестве и безлюдных местах, где стихают голоса и движения. Ничто не будет для него желаннее: там собираются воедино силы сердца и воли, закрываются двери, рассеивающие его устремление и разбрасывающие сердце. Он находит в этом отраду и чувствует отчуждение среди людей.')
a(344,'ثم يفتح له حلاوة العبادة بحيث لا يكاد يشبع منها، ويجد فيها من اللذة والراحة أضعاف ما كان يجده في لذة اللهو واللعب ونيل الشهوات، بحيث إذا دخل في الصلاة ود أن لا يخرج منها.','Затем ему открывается сладость поклонения, которой он почти не может насытиться. Он находит в нём удовольствие и покой, многократно превосходящие прежнее наслаждение развлечениями, забавами и удовлетворением страстей. Вступив в молитву, он желает уже не выходить из неё.')
a(345,'ثم يفتح له حلاوة استماع كلام الله فلا يشبع منه، وإذا سمعه هدأ قلبه به كما يهدأ الصبي إذا أعطي ما هو شديد المحبة له. ثم يفتح له شهود عظمة المتكلم به وجلاله، وكمال نعوته وصفاته وحكمته، ومعاني خطابه، بحيث يستغرق قلبه في ذلك حتى يغيب فيه، ويحس بقلبه قد دخل في عالم آخر غير ما الناس فيه.','Затем ему открывается сладость слушания речи Аллаха, и он не насыщается ею. Когда он слышит её, сердце его успокаивается, как успокаивается ребёнок, получив то, что очень любит. Затем ему открывается созерцание величия и славы Произнесшего её, совершенства Его качеств, атрибутов и мудрости и смыслов Его обращения. Сердце так погружается в это, что утрачивает внимание к остальному, и он ощущает, что сердцем вошёл в иной мир, отличный от того, в котором находятся люди.')
a(345,'ثم يفتح له باب الحياء من الله، وهو أول شواهد المعرفة. وهو نور يقع في القلب، يريه ذلك النور أنه واقف بين يدي ربه عز وجل، فيستحيي منه في خلواته وجلواته، ويرزق عند ذلك دوام المراقبة للقرب، ودوام التطلع إلى حضرة العلي الأعلى؛ حتى كأنه يراه ويشاهده فوق سماواته، مستويا على عرشه، ناظرا إلى خلقه، سامعا لأصواتهم، مشاهدا لبواطنهم. فإذا استولى عليه هذا الشاهد غطى عليه كثيرا من الهموم بالدنيا وما فيها، فهو في وجود والناس في وجود آخر، هو في وجود بين يدي ربه ووليه، ناظرا إليه بقلبه، والناس في حجاب عالم الشهادة في الدنيا، فهو يراهم وهم لا يرونه، ولا يرون منه إلا ما يناسب عالمهم ووجودهم.','Затем ему открывается дверь стыда перед Аллахом — первого из свидетельств познания. Это свет, нисходящий в сердце. Благодаря этому свету он видит, что стоит перед своим Господом, Всемогущим и Великим, и стыдится Его наедине и среди людей. Тогда ему даруются непрерывное бодрствование сердца вследствие близости и постоянное устремление к присутствию Всевышнего, Высочайшего. Он словно видит Его и созерцает над Его небесами, вознёсшимся над Своим Троном, взирающим на Свои творения, слышащим их голоса и видящим их сокровенное. Когда это созерцание овладевает им, оно заслоняет многие заботы о земном мире и его содержимом. Он пребывает в одном состоянии, а люди — в другом: он находится перед своим Господом и Покровителем, взирая на Него сердцем, а люди укрыты завесой земного видимого мира. Он видит их, а они его не видят; они видят в нём лишь то, что соответствует их миру и их состоянию.')
a(346,'ثم يفتح له الشعور بمشهد القيومية، فيرى سائر التقلبات الكونية وتصاريف الوجود بيده سبحانه وحده، فيشهده مالك الضر والنفع، والخلق والرزق، والإحياء والإماتة، فيتخذه وحده وكيلا، ويرضى به ربا ومدبرا وكافيا. وعند ذلك إذا وقع نظره على شيء من المخلوقات دله على خالقه وبارئه، وصفات كماله ونعوت جلاله، فلا يحجبه خلقه عنه سبحانه، بل يناديه كل من المخلوقات بلسان حاله: اسمع شهادتي من أحسن كل شيء خلقه، فأنا صنع الله الذي أتقن كل شيء.','Затем ему открывается ощущение поддержания Аллахом всего сущего. Он видит, что все перемены во вселенной и повороты бытия находятся в Руке одного Аллаха, Пречист Он. Он созерцает Его Владыкой вреда и пользы, творения и удела, оживления и умерщвления, избирает Его одного Попечителем и доволен Им как Господом, Управителем и Тем, Кто ему достаточен. Тогда любая вещь из творений, на которую падает его взгляд, указывает ему на своего Создателя и Творца, на Его совершенные атрибуты и величественные качества. Творения не заслоняют от него Аллаха, Пречист Он. Напротив, каждое творение взывает к нему самим своим состоянием: «Выслушай моё свидетельство о Том, Кто прекрасно создал всякую вещь: я — творение Аллаха, Который совершенным сделал всё».')
a(346,'فإذا استمر له ذلك فتح عليه باب القبض والبسط، فيقبض عليه حتى يجد ألم القبض لقوة وارده، ثم يفيض وعاؤه بأنوار الوجود، فيفنى عن وجوده، وينمحي كما يمحو نور الشمس نور الكواكب، ويطوى الكون عن قلبه بحيث لا يبقى فيه إلا الله الواحد القهار، وتفيض أنوار المعرفة والمعاملة والصدق والإخلاص والمحبة من قلبه، كما يفيض نور الشمس عن جرمها، فيغرق حينئذ في الأنوار كما يغرق راكب البحر في البحر. وذلك إنما يكون بعد الرياضة والمجاهدة، وزوال أحكام الطبيعة، وطول الوقوف في الباب.','Если это состояние сохраняется, ему открывается дверь сжатия и раскрытия. Сердце сжимается так, что он испытывает боль сжатия от силы приходящего переживания. Затем его вместилище переполняется светом обретения, и он утрачивает внимание к собственному бытию, которое словно стирается, как свет солнца стирает свет звёзд. Мир сворачивается для его сердца, и в нём не остаётся ничего, кроме Аллаха, Единственного, Всепокоряющего. Из сердца изливается свет познания, обращения с Господом, правдивости, искренности и любви, как свет исходит от солнечного диска. Он погружается в свет, подобно тому как плывущий по морю погружается в море. Это бывает лишь после воспитания души, борьбы с нею, исчезновения власти природных склонностей и долгого стояния у двери.')
a(347,'وهذا هو من علم اليقين، لا من عين اليقين، ولا من حق اليقين، إذ لا سبيل إليهما في هذه الدار، فإن عين اليقين مشاهدة، وحق اليقين مباشرة. نعم، قد يكون حق اليقين وعين اليقين في هذه الدنيا بالنسبة إلى الوجود الذهني وما يقوم بالقلوب فقط، ليس إلا، كما تقدم تقريره مرارا. ونحن لا تأخذنا في ذلك لومة لائم، وهم لا تأخذهم في كون ذلك في العيان لومة لائم، وهم عندنا صادقون ملبس عليهم، ونحن عندهم محجوبون عن ذلك غير واصلين إليه.','Это относится к знанию убеждённости, а не к непосредственному видению убеждённости и не к истине убеждённости: в этой обители к двум последним нет пути. Ведь непосредственное видение убеждённости — это созерцание, а истина убеждённости — непосредственное соприкосновение. Правда, в земной жизни они возможны применительно к мысленному бытию и тому, что происходит в сердцах, и только к этому, как неоднократно разъяснялось ранее. Нас не останавливает в этом порицание порицающего; их же не останавливает порицание порицающего в утверждении, что это происходит в действительном видении. Мы считаем их искренними, но введёнными в заблуждение, а они считают нас отделёнными завесой и не достигшими этого.')
a(347,'فإن استمر على حاله واقفا بباب مولاه، لا يلتفت عنه يمينا ولا شمالا، ولا يجيب غير من يدعوه إليه، ويعلم أن الأمر وراء ذلك، وأنه لم يصل بعد، ومتى توهم أنه قد وصل انقطع وانقطع عنه المزيد = رجي أن يفتح له فتح آخر، هو فوق ما كان فيه، فيستغرق قلبه في أنوار مشاهد الجلال بعد ظهور أنوار الوجود الحق، ومحو وجوده هو. ولا تتوهم أن وجود ذاته وصفاته يبطل، بل الذي يبطل: وجوده النفساني الطبيعي، ويبقى له وجود قلبي روحاني ملكي، فيبقى قلبه سابحا في بحر من أنوار آثار الجلال، فتنبع الأنوار من باطنه كنبع الماء من العين، حتى يجد الملكوت الأعلى كأنه في باطنه وقلبه، ويجد قلبه عاليا على ذلك كله، صاعدا إلى من ليس فوقه شيء.','Если он сохраняет своё состояние, стоя у двери своего Владыки, не отворачивается ни вправо, ни влево и отвечает лишь тому, кто зовёт его к Нему, зная, что за этим есть ещё нечто и что он пока не достиг цели, — ведь как только он вообразит, что достиг её, его продвижение прервётся и прибавление ему прекратится, — можно надеяться, что ему будет даровано новое открытие, превосходящее прежнее. Его сердце погрузится в свет созерцаний величия после явления света истинного обретения и стирания внимания к собственному бытию. Не думай, будто исчезают само его существование и его свойства. Исчезает его душевное, природное бытие, а остаётся бытие сердечное, духовное, ангельское. Его сердце продолжает плыть по морю света следов величия; свет бьёт из его глубины, как вода из источника, пока он не ощутит высшее небесное царство словно внутри себя, в своём сердце, а своё сердце — возвышающимся над всем этим и восходящим к Тому, над Кем нет ничего.')
a(347,'ثم يرقيه الله سبحانه، فيشهده أنوار الإكرام بعد ما شهد أنوار الجلال، فيستغرق في نور من أشعة الجمال. وفي هذا المشهد يذوق المحبة الخاصة الملهبة للأرواح والقلوب، فيبقى القلب مأسورا في يد حبيبه ووليه، ممتحنا بحبه.','Затем Аллах, Пречист Он, возвышает его и после света величия даёт ему созерцать свет почтения и щедрости. Он погружается в свет лучей красоты. В этом созерцании он вкушает особую любовь, воспламеняющую дух и сердце. Сердце остаётся пленником в Руке своего Возлюбленного и Покровителя, испытанным любовью к Нему.')
a(348,'وإن شئت أن تفهم ذلك تقريبا، فانظر إليك — أو إلى غيرك — وقد امتحنت بصورة بديعة الجمال ظاهرا وباطنا، فملكت عليك قلبك وفكرك، وليلك ونهارك؛ فيحصل له نار من المحبة تضرم في أحشائه يقل معها الاصطبار، وذلك فضل الله يؤتيه من يشاء.','Если хочешь приблизительно понять это, посмотри на себя или на другого, когда человек испытан обликом, дивно прекрасным внешне и внутренне, который всецело овладел его сердцем и мыслью, ночью и днём. Тогда в его груди вспыхивает огонь любви, перед которым слабеет терпение. Это милость Аллаха, которую Он дарует кому пожелает.')
a(348,'فيا له من قلب ممتحن مغمور مستغرق بما ظهر له من أشعة أنوار الجمال الأحدي! والناس مفتونون ممتحنون بما يفنى من المال والصور والرياسة، معذبون بذلك قبل حصوله وحال حصوله وبعد حصوله، وأعلاهم مرتبة من يكون مفتونا بالحور العين، أو عاملا على تمتعه في الجنة بالأكل والشرب واللباس والنكاح.','Каково же сердце, испытанное, затопленное и всецело поглощённое явившимися ему лучами света красоты Единственного! А люди пленены и испытаны преходящим богатством, обликами и властью. Они мучаются этим до приобретения, во время обладания и после него. Выше всего среди них тот, кто пленён черноокими гуриями или трудится ради наслаждения в Раю пищей, питьём, одеждой и супружеской близостью.')
a(348,'وهذا المحب قد ترقى في درجات المحبة على أهل المقامات، ينظرون إليه في الجنة كما ينظر إلى الكوكب الدري الغابر في الأفق لعلو درجته وقرب منزلته من حبيبه ومعيته معه، فإن المرء مع من أحب، ولكل عمل جزاء وجزاء المحبة: المحبة والوصول والاصطناع والقرب، فهذا هو الذي يصلح، وكفى بذلك شرفا وفخرا في عاجل الدنيا، فما ظنك بمقاماتهم العالية عند مليك مقتدر؟ كيف إذا رأيتهم في موقف القيامة، وقد أسمعهم المنادي: لينطلق كل قوم مع ما كانوا يعبدون، فيبقون في مكانهم ينتظرون معبودهم وحبيبهم الذي هو أحب شيء','Этот любящий поднялся по ступеням любви выше обладателей духовных стоянок. В Раю они будут смотреть на него, как смотрят на яркую звезду, уходящую за горизонт, из-за высоты его степени и близости его положения к Возлюбленному и пребывания с Ним. Ведь человек будет с тем, кого любит. Каждому делу есть воздаяние, а воздаяние за любовь — любовь, достижение, избрание для Себя и близость. Вот что достойно стремления; уже в земной жизни этого довольно для почёта и славы. Что же ты думаешь об их высоких стоянках у Всемогущего Властелина? Какими ты увидишь их на месте стояния в День воскресения, когда глашатай возвестит им: «Пусть каждый народ отправится с тем, чему поклонялся!» Они останутся на своих местах, ожидая Того, Кому поклонялись, своего Возлюбленного, Который им дороже всего')
obj={'pages':[dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pages[n]) for n in pages], 'units':units,'boundary_notes':[], 'review_notes':[]}
